    14→        my $nodes = $graph->nodes();
    15→
    16→        # Return minimal graph if empty
    17→        return join("\n", @lines) if scalar(keys %{$nodes}) == 0;
    18→
    19→        # Generate node declarations with labels
    20→        for my $node_id (sort keys %{$nodes}) {
    21→            my $node = $nodes->{$node_id};
