{
    my $ctx = Chalk::IR::Context->empty_context();
    my $heap = Chalk::IR::Heap->empty_heap();

    my ($ctx1, $heap1) = Chalk::IR::Reference->ref_new($ctx, $heap, 'value', 'v1');
    my $heap2 = Chalk::IR::Reference->ref_write($ctx1, $heap1, 'value', 'v2');
