   423→    method build_loop_phi_node($loop_node, $initial_value, $loop_value = undef) {
   424→        # Loop phi starts with control and initial value
   425→        # Loop value added later (lazy phi pattern)
   426→        my @inputs = ($loop_node->id, $initial_value);
   427→        push @inputs, $loop_value if defined $loop_value;
   428→
   429→        my $node_id = $self->next_node_id();
   430→        my $phi = Chalk::IR::Node::Phi->new(
   431→            id            => $node_id,
   432→            inputs        => \@inputs,
   433→            region_id     => $loop_node->id,
   434→        );
   435→        $graph->add_node($phi);
   436→        return $phi;
   437→    }
