   478→    method generate_loop_phi_nodes($loop_node) {
   479→        # Generate phi nodes for all variables modified within the loop
   480→        return {} unless $loop_tracking_active;
   481→        return {} unless defined $loop_entry_scope;
   482→
   483→        # Capture current (loop-end) values before creating phis
   484→        my $loop_end_scope = $scope->snapshot_bindings();
   485→
   486→        # Find which variables were modified in the loop
   487→        my @modified_vars = $scope->find_modified_variables($loop_entry_scope);
   488→
   489→        # Generate a phi node for each modified variable
   490→        my %phis = ();
   491→        for my $var (@modified_vars) {
   492→            my $initial_value = $loop_entry_scope->{$var};
   493→            my $loop_value = $loop_end_scope->{$var};
   494→
   495→            # Create phi with initial value; backedge added later
   496→            my $phi = $self->build_loop_phi_node($loop_node, $initial_value, $loop_value);
   497→            $phis{$var} = $phi;
   498→
   499→            # Update scope to use phi node for this variable
   500→            # This ensures uses after the loop see the phi
   501→            $scope->define($var, $phi->id);
   502→        }
   503→
   504→        return \%phis;
   505→    }
