   526→    method build_new_node($class_name, $field_values_hash) {
   527→        # Create New node for object instantiation
   528→        # $field_values_hash is a hashref mapping field names to node objects
   529→        my @input_nodes = ($current_control);
   530→        my %field_value_refs;
   531→
   532→        # Build field references from hash
   533→        for my $field_name (sort( keys( $field_values_hash->%* ) )) {
   534→            my $value_node = $field_values_hash->{$field_name};
   535→            push @input_nodes, $value_node->id;
   536→            $field_value_refs{$field_name} = {
   537→                op => 'NodeRef',
   538→                node_id => $value_node->id
   539→            };
   540→        }
   541→
   542→        my $attributes = {
   543→            class => $class_name,
   544→            field_values => \%field_value_refs
   545→        };
   546→        my $node_id = $self->next_node_id();
   547→        my $new_obj = Chalk::IR::Node->new(
   548→            id            => $node_id,
   549→            op            => 'New',
   550→            inputs        => \@input_nodes,
   551→            attributes    => $attributes,
   552→        );
   553→        $graph->add_node($new_obj);
   554→        return $new_obj;
   555→    }
