        return $array_new;
    }

    method build_array_push_node($array_node, $value_node) {
        # Create ArrayPush node for appending to array
        my $array_ref = { op => 'NodeRef', node_id => $array_node->id };
        my $value_ref = { op => 'NodeRef', node_id => $value_node->id };
        my $attributes = {
            array => $array_ref,
