    method build_array_get_node($array_node, $index_node) {
        # Create ArrayGet node for accessing array element by index
        my $array_ref = { op => 'NodeRef', node_id => $array_node->id };
        my $index_ref = { op => 'NodeRef', node_id => $index_node->id };
        my $attributes = {
