    method build_hash_set_node($hash_node, $key_node, $value_node) {
        # Create HashSet node for setting a hash key/value pair
        my $hash_ref = { op => 'NodeRef', node_id => $hash_node->id };
        my $key_ref = { op => 'NodeRef', node_id => $key_node->id };
