        # Create StrConcat node for concatenating two strings
        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };

        my $attributes = {
            left => $left_ref,
            right => $right_ref
