        # inputs[2] = value node
        my @inputs = $self->inputs->@*;

        my $address = $values->{$inputs[1]};
        my $value = $values->{$inputs[2]};

        # Write to heap
        $heap->{$address} = $value;

        # Return memory state token
        return 1;
    }
}

