    $result = $node->execute();
} elsif ($heap_ops{$op}) {
    $result = $node->execute(\%values, \%heap);
} elsif ($value_ops{$op}) {
    $result = $node->execute(\%values);
} else {
    die "Unknown op type: $op";
}

