     8→
     9→class Chalk::IR::Reference {
    10→    # Creates new reference: allocates on heap, binds address in context
    11→    # Returns (new_context, new_heap)
    12→    sub ref_new($class, $ctx, $heap, $label, $value) {
    13→        # Allocate value on heap
    14→        my ($new_heap, $addr) = Chalk::IR::Heap->heap_alloc($heap, $value);
    15→
    16→        # Bind address in context
    17→        my $new_ctx = Chalk::IR::Context->extend_context($ctx, $label, $addr);
    18→
    19→        return ($new_ctx, $new_heap);
    20→    }
    21→
    22→    # Dereferences label: looks up address, reads from heap
    23→    # Returns value (or undef if label not found or address invalid)
    24→    sub ref_read($class, $ctx, $heap, $label) {
    25→        # Look up address in context
    26→        my $addr = $ctx->($label);
    27→        return undef unless defined $addr;
    28→
    29→        # Read value from heap
    30→        return Chalk::IR::Heap->heap_read($heap, $addr);
    31→    }
    32→
    33→    # Updates reference: looks up address, writes to heap
    34→    # Returns new_heap (context unchanged since address stays same)
    35→    sub ref_write($class, $ctx, $heap, $label, $new_value) {
    36→        # Look up address in context
    37→        my $addr = $ctx->($label);
    38→        return $heap unless defined $addr;
    39→
    40→        # Write new value to heap
    41→        return Chalk::IR::Heap->heap_write($heap, $addr, $new_value);
    42→    }
    43→}

